// LAB: Test an alias-sensitive rewrite
// Implement write_then_read(a,b) and verify both separate objects and two references to the same object. Do not move the read before the write.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    int x = 4;
    int& a = x;
    int& b = x;
    const int remembered = b;
    a = 9;
    const int after = b;
    std::cout << remembered << ' ' << after << '\n';
    assert(remembered == 4 && after == 9);
}

#include <cassert>
#include <iostream>

int write_then_read(int& a, const int& b) { a = 9; return b; }
int cached_before(int& a, const int& b) { const int old = b; a = 9; return old; }

int main() {
    int a = 4, b = 6;
    assert(write_then_read(a,b) == 6 && a == 9);
    int x = 4;
    const int correct = write_then_read(x,x);
    x = 4;
    const int changed = cached_before(x,x);
    assert(correct == 9 && changed == 4);
    std::cout << "ordered=" << correct << " reordered=" << changed << '\n';
}

